<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Robot-Manipulation Demonstration Collection Systems</title>
<style>
  :root{
    --bg:#f6f8fa; --card:#ffffff; --ink:#1a202c; --muted:#5a6472;
    --line:#d7dee6; --accent:#1f6feb; --good:#1a7f37; --warn:#9a6700;
    --method-colors:#1f6feb #2e8b57 #b8860b #7b3fb3 #c2185b #455a64 #00838f #8d6e63;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;padding:16px}
  h1{font-size:1.5rem;margin:.2em 0 .6em}
  h2{font-size:1.15rem;margin:1.4em 0 .5em}
  .wrap{max-width:1200px;margin:0 auto}
  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:1em 0}
  .card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px}
