  .filters{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  @media(min-width:640px){.filters{grid-template-columns:2fr 1fr 1fr 1fr}}
  .note{background:#fff8e6;border:1px solid #f0d784;border-radius:8px;padding:10px 12px;font-size:.88rem;color:#6b5300;margin:1em 0}
